import DOMPurify from 'isomorphic-dompurify'
import { HTML_SANITIZE_CONFIG } from './sanitizeConfig'
import { applyDomPurifyHooks } from './sanitizeHooks'

applyDomPurifyHooks(DOMPurify)

/** Sanitize HTML on both SSR and client with a fixed allowlist. */
export function sanitizeHtml(html: string): string {
  if (!html) return ''
  return DOMPurify.sanitize(html, HTML_SANITIZE_CONFIG)
}
